export function FindAndReplace({
  findText = "{{findText}}",
  replaceText = "{{replaceText}}",
  matchCount = {{matchCount}},
  matchCase = {{matchCase}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2",
      border: "1.5px solid #24143022", borderRadius: 10, padding: 12, maxWidth: 300 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 4px" }}>
        <svg viewBox="0 0 20 20" width="14" height="14" aria-hidden="true"><circle cx="8.5" cy="8.5" r="6" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="M13 13l4 4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></svg>
        <input type="text" readOnly value={findText} aria-label="Find" style={{ flex: 1, minWidth: 0, border: "1.5px solid #24143033", borderRadius: 6, padding: "5px 8px", font: "inherit", color: "#241430", background: "#fff" }} />
        <span style={{ fontSize: 12, color: "#24143099", whiteSpace: "nowrap" }}>{matchCount} matches</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 4px" }}>
        <svg viewBox="0 0 20 20" width="14" height="14" aria-hidden="true"><path d="M4 10h9M13 10l-3-3M13 10l-3 3" stroke="currentColor" strokeWidth="1.6" fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
        <input type="text" readOnly value={replaceText} aria-label="Replace with" style={{ flex: 1, minWidth: 0, border: "1.5px solid #24143033", borderRadius: 6, padding: "5px 8px", font: "inherit", color: "#241430", background: "#fff" }} />
        <button type="button" style={{ marginLeft: "auto", border: "none", background: accent, color: "#241430", fontSize: 12, fontWeight: 600, padding: "6px 10px", borderRadius: 6, cursor: "pointer" }}>Replace all</button>
      </div>
      <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 4px 2px", fontSize: 13, cursor: "pointer" }}>
        <span style={{ width: 30, height: 17, borderRadius: 999, position: "relative", display: "inline-block",
          background: matchCase ? accent : "#24143033" }}>
          <span className="far-thumb" style={{ position: "absolute", top: 2, left: matchCase ? 15 : 2, width: 13, height: 13, borderRadius: "50%", background: "#fff" }} />
        </span>
        <span>Match case</span>
      </label>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .far-thumb { transition: left .15s; }
        }
      `}</style>
    </div>
  );
}
